// Module-Level Convenience Functions
// ============================================================================

object Tokenizer {
  /**
   * Tokenize a single value using the universal tokenizer.
   */
  def tokenize(value: Any): Token = {
    val tokenizer = new UniversalTokenizer()
    tokenizer.tokenize(value)
  }

  /**
   * Tokenize a batch of values.
   */
  def tokenizeBatch(values: Seq[Any]): Seq[Token] = {
    val tokenizer = new UniversalTokenizer()
    tokenizer.tokenizeSeq(values)
  }

  /**
   * Create a token directly with optional metadata.
   */
  def toToken(value: String, tokenType: TokenType = TokenType.STRING): Token =
    Token(value, tokenType)

  /**
   * Create a token with metadata.
   */
  def toTokenWithMetadata(
    value: String,
    tokenType: TokenType,
    metadata: (String, Any)*
  ): Token =
    Token(value, tokenType, metadata.toMap)

  /**
   * Batch tokenize text by whitespace.
   */
  def tokenizeText(text: String): Seq[Token] = {
    val tokenizer = new WhitespaceTokenizer()
    tokenizer.tokenize(text)
  }

  /**
   * Create a token builder for custom tokenization.
   */
  def builder[T]: TokenizerBuilder[T] = new TokenizerBuilder[T]()

  /**
   * Create a universal tokenizer instance.
   */
  def universal: UniversalTokenizer = new UniversalTokenizer()

  /**
   * Create a string tokenizer instance.
   */
  def string: StringTokenizer = new StringTokenizer()

  /**
   * Create a numeric tokenizer instance.
   */
  def numeric: NumericTokenizer = new NumericTokenizer()

  /**
   * Create a temporal tokenizer instance.
   */
  def temporal: TemporalTokenizer = new TemporalTokenizer()

  /**
   * Create a whitespace tokenizer instance.
   */
  def whitespace: WhitespaceTokenizer = new WhitespaceTokenizer()

  /**
   * Create a JSON tokenizer instance.
   */
  def json(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

