/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * Scala translation of Python tokenizer with the following features:
 * - Sealed trait hierarchies for type safety
 * - Case classes for immutable data structures
 * - Type classes for extensible tokenization
 * - Pattern matching for polymorphic dispatch
 * - Option/Try for error handling
 * - Variance annotations for generic types
 * - Scala collections and functional APIs
 */

import scala.util.{Try, Success, Failure}
import scala.collection.immutable.{Seq, Map, Set}
import scala.io.Codec
import java.time.{LocalDate, LocalDateTime, ZonedDateTime}
import java.time.format.DateTimeFormatter
import java.math.{BigDecimal => JavaBigDecimal}
import scala.math.BigDecimal
import scala.reflect.ClassTag

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { override def value: String = "string" }
  case object NUMERIC extends TokenType { override def value: String = "numeric" }
  case object TEMPORAL extends TokenType { override def value: String = "temporal" }
  case object STRUCTURED extends TokenType { override def value: String = "structured" }
  case object BINARY extends TokenType { override def value: String = "binary" }
  case object NULL extends TokenType { override def value: String = "null" }

  def apply(str: String): Option[TokenType] = str match {
    case "string" => Some(STRING)
    case "numeric" => Some(NUMERIC)
    case "temporal" => Some(TEMPORAL)
    case "structured" => Some(STRUCTURED)
    case "binary" => Some(BINARY)
    case "null" => Some(NULL)
    case _ => None
  }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 *
 * @param value The token string value
 * @param tokenType The type of token
 * @param metadata Additional metadata about the token
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   *
   * @param newMetadata Key-value pairs to add to metadata
   * @return A new Token with merged metadata
   */
  def withMetadata(newMetadata: (String, Any)*): Token =
    copy(metadata = metadata ++ newMetadata.toMap)

  /**
   * Extract metadata value by key.
   *
   * @param key The metadata key
   * @return Some(value) if present, None otherwise
   */
  def getMetadata(key: String): Option[Any] =
    metadata.get(key)
}

/**
 * Mutable batch of tokens for processing.
 * Provides state management for batch operations.
 */
class TokenBatch {
  private var tokens: scala.collection.mutable.ListBuffer[Token] =
    scala.collection.mutable.ListBuffer.empty
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens += token
  }

  def addAll(ts: Seq[Token]): Unit = {
    if (_processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens ++= ts
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def isProcessed: Boolean = _processed

  def getTokens: Seq[Token] = tokens.toSeq

  def size: Int = tokens.size
}

// ============================================================================
// Type Classes for Tokenization
// ============================================================================

/**
 * Type class for types that can be converted to tokens.
 * Enables extension of tokenization without modifying existing types.
 */
trait Tokenizable[T] {
  def toToken(value: T): Token
}

object Tokenizable {
  def apply[T](implicit instance: Tokenizable[T]): Tokenizable[T] = instance

  implicit val stringTokenizable: Tokenizable[String] =
    (value: String) => Token(value, TokenType.STRING)

  implicit val intTokenizable: Tokenizable[Int] =
    (value: Int) => Token(value.toString, TokenType.NUMERIC, Map("originalType" -> "Int"))

  implicit val longTokenizable: Tokenizable[Long] =
    (value: Long) => Token(value.toString, TokenType.NUMERIC, Map("originalType" -> "Long"))

  implicit val floatTokenizable: Tokenizable[Float] =
    (value: Float) => Token(f"$value%.6f", TokenType.NUMERIC, Map("originalType" -> "Float"))

  implicit val doubleTokenizable: Tokenizable[Double] =
    (value: Double) => Token(f"$value%.6f", TokenType.NUMERIC, Map("originalType" -> "Double"))

  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] =
    (value: BigDecimal) => Token(value.toString, TokenType.NUMERIC, Map("originalType" -> "BigDecimal"))
}

/**
 * Type class for types that have length.
 */
trait HasLength[T] {
  def length(value: T): Int
}

object HasLength {
  implicit val stringHasLength: HasLength[String] = (value: String) => value.length
  implicit def seqHasLength[T]: HasLength[Seq[T]] = (value: Seq[T]) => value.length
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * The +T variance allows this container to be covariant.
 */
class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items

  def mapTokens[U](func: T => String): Seq[String] =
    items.map(func)

  def size: Int = items.size

  def isEmpty: Boolean = items.isEmpty
}

object TokenContainer {
  def apply[T](items: T*): TokenContainer[T] = new TokenContainer(items.toSeq)
  def empty[T]: TokenContainer[T] = new TokenContainer(Seq.empty)
}

/**
 * Contravariant sink - can accept supertypes.
 * The -T variance allows this sink to be contravariant.
 */
class TokenSink[-T] {
  private val received: scala.collection.mutable.ListBuffer[Any] =
    scala.collection.mutable.ListBuffer.empty

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): Seq[Any] = {
    val result = received.toSeq
    received.clear()
    result
  }

  def size: Int = received.size
}

/**
 * Invariant handler - exact type matching required.
 */
class BivariantHandler[T](initialValue: T) {
  private var _value: T = initialValue

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Type Hierarchy
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Defines the interface for all tokenizers.
 */
abstract class BaseTokenizer[T] {
  /**
   * Convert a single value to a token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values using an Iterator.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Tokenize multiple values into a Seq.
   */
  def tokenizeSeq(values: Iterable[T]): Seq[Token] =
    values.map(tokenize).toSeq
}

/**
 * Tokenizer for string types (String and Array[Byte]).
 * Handles encoding and optional normalization.
 */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: Option[String => String] = None
) extends BaseTokenizer[String] {
  private val norm = normalizer.getOrElse(identity)

  def tokenize(value: String): Token = {
    val normalized = norm(value)
    Token(normalized, TokenType.STRING)
  }

  def tokenizeBytes(bytes: Array[Byte]): Token = {
    val str = new String(bytes, encoding)
    tokenize(str)
  }
}

object StringTokenizer {
  def apply(): StringTokenizer = new StringTokenizer()
  def apply(encoding: String): StringTokenizer = new StringTokenizer(encoding)
  def apply(normalizer: String => String): StringTokenizer =
    new StringTokenizer(normalizer = Some(normalizer))
  def apply(encoding: String, normalizer: String => String): StringTokenizer =
    new StringTokenizer(encoding, Some(normalizer))
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, String] = Map.empty
) extends BaseTokenizer[Number] {

  def tokenize(value: Number): Token = value match {
    case i: Int =>
      Token(i.toString, TokenType.NUMERIC, Map("originalType" -> "Int"))
    case l: Long =>
      Token(l.toString, TokenType.NUMERIC, Map("originalType" -> "Long"))
    case f: Float =>
      Token(f"%${precision}f".format(f), TokenType.NUMERIC, Map("originalType" -> "Float"))
    case d: Double =>
      Token(f"%${precision}f".format(d), TokenType.NUMERIC, Map("originalType" -> "Double"))
    case bd: java.math.BigDecimal =>
      Token(bd.toString, TokenType.NUMERIC, Map("originalType" -> "BigDecimal"))
    case bd: scala.math.BigDecimal =>
      Token(bd.toString, TokenType.NUMERIC, Map("originalType" -> "BigDecimal"))
    case _ =>
      Token(value.toString, TokenType.NUMERIC)
  }
}

object NumericTokenizer {
  def apply(): NumericTokenizer = new NumericTokenizer()
  def apply(precision: Int): NumericTokenizer = new NumericTokenizer(precision)
}

/**
 * Tokenizer for temporal types (LocalDate, LocalDateTime, etc.)
 */
class TemporalTokenizer(
  customFormat: Option[DateTimeFormatter] = None
) extends BaseTokenizer[java.time.temporal.Temporal] {

  private val defaultDateFormat = DateTimeFormatter.ISO_LOCAL_DATE
  private val defaultDateTimeFormat = DateTimeFormatter.ISO_LOCAL_DATE_TIME

  def tokenize(value: java.time.temporal.Temporal): Token = {
    val formatter = customFormat.getOrElse {
      value match {
        case _: LocalDateTime => defaultDateTimeFormat
        case _: ZonedDateTime => defaultDateTimeFormat
        case _: LocalDate => defaultDateFormat
        case _ => DateTimeFormatter.ISO_INSTANT
      }
    }
    Token(value.toString, TokenType.TEMPORAL)
  }

  def tokenizeLocalDate(date: LocalDate): Token =
    Token(date.format(defaultDateFormat), TokenType.TEMPORAL)

  def tokenizeLocalDateTime(dateTime: LocalDateTime): Token =
    Token(dateTime.format(defaultDateTimeFormat), TokenType.TEMPORAL)
}

object TemporalTokenizer {
  def apply(): TemporalTokenizer = new TemporalTokenizer()
  def apply(format: DateTimeFormatter): TemporalTokenizer =
    new TemporalTokenizer(Some(format))
}

// ============================================================================
// Universal Tokenizer - Polymorphic Dispatch
// ============================================================================

/**
 * Universal tokenizer that handles multiple types with pattern matching.
 * Uses Scala's type system for safe, efficient dispatch.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Tokenize any value by pattern matching on its runtime type.
   * Falls back to string conversion for unknown types.
   */
  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.NULL)

    case s: String =>
      stringTokenizer.tokenize(s)

    case b: Array[Byte] =>
      stringTokenizer.tokenizeBytes(b)

    case i: Int =>
      numericTokenizer.tokenize(i)

    case l: Long =>
      numericTokenizer.tokenize(l)

    case f: Float =>
      numericTokenizer.tokenize(f)

    case d: Double =>
      numericTokenizer.tokenize(d)

    case bd: scala.math.BigDecimal =>
      numericTokenizer.tokenize(bd)

    case bd: java.math.BigDecimal =>
      numericTokenizer.tokenize(bd)

    case ld: LocalDate =>
      temporalTokenizer.tokenizeLocalDate(ld)

    case ldt: LocalDateTime =>
      temporalTokenizer.tokenizeLocalDateTime(ldt)

    case zdt: ZonedDateTime =>
      Token(zdt.toString, TokenType.TEMPORAL)

    case t: java.util.Date =>
      Token(t.toString, TokenType.TEMPORAL)

    case m: Map[String, Any] =>
      toJsonToken(m)

    case _ =>
      Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }

  private def toJsonToken(map: Map[String, Any]): Token = {
    val jsonStr = map.map { case (k, v) =>
      s""""$k": ${valueToJsonString(v)}"""
    }.mkString("{", ", ", "}")
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  private def valueToJsonString(value: Any): String = value match {
    case null => "null"
    case s: String => s""""$s""""
    case n: Number => n.toString
    case b: Boolean => b.toString
    case m: Map[String, Any] => m.map { case (k, v) =>
      s""""$k": ${valueToJsonString(v)}"""
    }.mkString("{", ", ", "}")
    case s: Seq[Any] => s.map(valueToJsonString).mkString("[", ", ", "]")
    case _ => s""""${value.toString}""""
  }

  /**
   * Tokenize a sequence of values, delegating to tokenize for each.
   */
  def tokenizeSeq(values: Seq[Any]): Seq[Token] =
    values.map(tokenize)
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer()
}

// ============================================================================
// Token Registry - Complex Generic Types
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Supports registering token containers and handlers for polymorphic processing.
 */
class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: scala.collection.mutable.ListBuffer[T => Option[Token]] =
    scala.collection.mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Seq[Option[Token]] = {
    registry.get(key) match {
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator.map(_(item)).find(_.isDefined).flatten
        }
      case None => Seq.empty
    }
  }

  def getRegistry: Map[String, TokenContainer[T]] = registry

  def clearRegistry(): Unit = {
    registry = Map.empty
  }
}

object TokenRegistry {
  def apply[T](): TokenRegistry[T] = new TokenRegistry[T]()
}

// ============================================================================
// Functor and Monad for Tokens
// ============================================================================

/**
 * Functor wrapper for tokens with map operations.
 */
trait TokenFunctor[T] {
  def value: T

  def map[U](func: T => U): TokenFunctor[U] =
    TokenFunctor.Wrapped(func(value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] =
    func(value)

  def getOrElse(default: => T): T =
    if (value != null) value else default
}

object TokenFunctor {
  case class Wrapped[T](value: T) extends TokenFunctor[T]

  def apply[T](v: T): TokenFunctor[T] = Wrapped(v)
  def pure[T](v: T): TokenFunctor[T] = Wrapped(v)
}

/**
 * Monad extension with applicative operations.
 */
trait TokenMonad[T] extends TokenFunctor[T] {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U]
}

object TokenMonad {
  case class Wrapped[T](value: T) extends TokenMonad[T] {
    def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
      funcWrapped match {
        case Wrapped(func) => Wrapped(func(value))
      }
  }

  def pure[T](value: T): TokenMonad[T] = Wrapped(value)
}

// ============================================================================
// JSON Tokenization
// ============================================================================

/**
 * Tokenizer for JSON structures.
 * Handles recursive JSON types with proper formatting.
 */
class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Map[String, Any]): Token = {
    val jsonStr = if (pretty) {
      prettyPrintJson(value, 0)
    } else {
      compactJson(value)
    }
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizeValue(value: Any): Token = {
    val jsonStr = if (pretty) {
      prettyPrintJsonValue(value, 0)
    } else {
      compactJsonValue(value)
    }
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Any, path: String): Option[Token] = {
    extractPath(value, path.split("\\.").toList)
      .map(v => tokenizeValue(v))
  }

  private def extractPath(value: Any, parts: List[String]): Option[Any] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case map: Map[String, Any] =>
          map.get(head).flatMap(extractPath(_, tail))
        case seq: Seq[Any] =>
          Try(head.toInt).toOption.flatMap { idx =>
            if (idx >= 0 && idx < seq.length) {
              extractPath(seq(idx), tail)
            } else {
              None
            }
          }
        case _ => None
      }
  }

  private def compactJson(value: Any): String = value match {
    case null => "null"
    case map: Map[String, Any] =>
      map.map { case (k, v) => s""""$k":${compactJson(v)}""" }
        .mkString("{", ",", "}")
    case seq: Seq[Any] =>
      seq.map(compactJson).mkString("[", ",", "]")
    case s: String => s""""$s""""
    case _ => value.toString
  }

  private def compactJsonValue(value: Any): String = compactJson(value)

  private def prettyPrintJson(map: Map[String, Any], indent: Int): String = {
    val innerIndent = " " * (indent + 2)
    val closeIndent = " " * indent
    val items = map.map { case (k, v) =>
      s"""$innerIndent"$k": ${prettyPrintJsonValue(v, indent + 2)}"""
    }.mkString(",\n")
    s"{\n$items\n$closeIndent}"
  }

  private def prettyPrintJsonValue(value: Any, indent: Int): String = {
    val innerIndent = " " * (indent + 2)
    val closeIndent = " " * indent
    value match {
      case null => "null"
      case map: Map[String, Any] =>
        val items = map.map { case (k, v) =>
          s"""$innerIndent"$k": ${prettyPrintJsonValue(v, indent + 2)}"""
        }.mkString(",\n")
        s"{\n$items\n$closeIndent}"
      case seq: Seq[Any] =>
        val items = seq.map(v => s"$innerIndent${prettyPrintJsonValue(v, indent + 2)}")
          .mkString(",\n")
        s"[\n$items\n$closeIndent]"
      case s: String => s""""$s""""
      case _ => value.toString
    }
  }
}

object JsonTokenizer {
  def apply(): JsonTokenizer = new JsonTokenizer()
  def apply(pretty: Boolean): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Supports filtering, normalization, and position tracking.
 *
 * This is a fundamental tokenization operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  /**
   * Process a single word into a token string.
   */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains)
        .reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    if (maxLength.exists(processed.length > _)) {
      processed = processed.take(maxLength.get)
    }

    if (processed.nonEmpty) Some(processed) else None
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): Seq[Token] = {
    val words = text.split("\\s+").toList
    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): Seq[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): Seq[(String, Int, Int)] = {
    var currentPos = 0
    text.split("\\s+").flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      val result = processToken(word).map { processed =>
        (processed, start, end)
      }
      currentPos = end
      result
    }.toSeq
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int =
    tokenize(text).length
}

object WhitespaceTokenizer {
  def apply(): WhitespaceTokenizer = new WhitespaceTokenizer()
  def apply(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer =
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers with custom configurations.
 * Uses the builder pattern with method chaining for fluent API.
 */
class TokenizerBuilder[T] {
  private var normalizers: scala.collection.mutable.ListBuffer[String => String] =
    scala.collection.mutable.ListBuffer.empty
  private var validators: scala.collection.mutable.ListBuffer[T => Boolean] =
    scala.collection.mutable.ListBuffer.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(newMetadata: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ newMetadata.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   * Returns a function that tokenizes values with accumulated configurations.
   */
  def build(): T => Token = { value: T =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadata)
  }

  /**
   * Build with Try for error handling.
   */
  def buildSafe(): T => Try[Token] = { value: T =>
    Try {
      // Validate
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

